<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $controller = app()->make("App\Http\Controllers\Api\POAFichasController"); $request = Illuminate\Http\Request::create("/api/poa/fichas?ejercicio_id=2026&area_id=1", "GET"); $response = $controller->getFichas($request); $data = json_decode($response->getContent(), true); foreach($data as $p) { echo "Proyecto: " . $p["nombre"] . "\n"; foreach($p["acciones"] as $a) { echo "  Accion: " . substr($a["descripcion"] ?? $a["texto"], 0, 30) . "...\n"; echo "    Riesgos: " . count($a["riesgos_vinculados"]) . "\n"; } }
